// Curio Class Recess shell: what every Recess game does the same way, and nothing else (docs/GAMES.md).
// Shared shell bundled locally; see kit/recess.js for the original header.
// The game owns its whole world (board, art, motion, sound design). The shell owns only: the corner controls (Undo,
// Restart, Sound, Motion, Scores), stars and personal bests per level, the 3-letter local high score board, the
// win card, a seeded daily puzzle, a few synth sounds and a particle burst. Everything saves on this device only.
//
//   Recess.start({id, title, score: {label: 'Moves', lower: true}, onUndo, onRestart, onNext})
//   Recess.level(key, label)       say which level is on (key is stored, label is shown)
//   Recess.canUndo(bool)           enable or disable Undo
//   Recess.win({score, stars})     finish the level: shows the card, saves stars and best, asks for initials on a top 10
//   Recess.stars(key) / Recess.totalStars() / Recess.best(key)
//   Recess.play(name)              'tap' 'place' 'clack' 'slide' 'pop' 'capture' 'win' 'nope'
//   Recess.burst(x, y, colors)     a small confetti burst at page coordinates (skipped in calm motion)
//   Recess.rng(seed) / Recess.daily()   seeded random (daily() is today's, the same for everyone that day)
//   Recess.calm / Recess.onMotion(fn) / Recess.store(key, value?)
const Recess = (() => {
  const $ = id => document.getElementById(id);
  const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
  let cfg = {id: 'game', title: 'Recess', score: {label: 'Score', lower: false}};
  let levelKey = 'main', levelLabel = '', undoOk = false;

  // ---------- storage: one namespace per game, never fails the game ----------
  function store(key, value) {
    const k = `recess:${cfg.id}:${key}`;
    try {
      if (value === undefined) { const v = localStorage.getItem(k); return v == null ? null : JSON.parse(v); }
      localStorage.setItem(k, JSON.stringify(value));
    } catch {}
    return value;
  }

  // ---------- motion and sound, shared with the classroom tools' settings ----------
  let calm = matchMedia('(prefers-reduced-motion: reduce)').matches;
  try { const m = localStorage.getItem('curio-motion'); if (m) calm = m === 'calm'; } catch {}
  let sound = true;
  try { sound = localStorage.getItem('recess-sound') !== 'off'; } catch {}
  const motionFns = [];

  let ac = null;
  function audio() {
    if (!ac) { const A = window.AudioContext || window.webkitAudioContext; if (A) ac = new A(); }
    if (ac && ac.state === 'suspended') ac.resume();
    return ac;
  }
  // tiny synth voices: [frequency, end frequency, seconds, wave, volume, noise]
  const SOUNDS = {
    tap: [[660, 640, .05, 'sine', .12]],
    place: [[220, 150, .09, 'triangle', .3], [0, 0, .04, 'noise', .08]],
    clack: [[0, 0, .05, 'noise', .25], [1800, 1200, .03, 'square', .05]],
    slide: [[0, 0, .14, 'noise', .07]],
    pop: [[420, 900, .08, 'sine', .22]],
    capture: [[520, 260, .18, 'triangle', .22], [0, 0, .12, 'noise', .07]],
    nope: [[200, 170, .16, 'sawtooth', .07]],
    win: [[523, 523, .12, 'triangle', .2], [659, 659, .12, 'triangle', .2, 0, .1], [784, 784, .12, 'triangle', .2, 0, .2], [1047, 1047, .3, 'triangle', .22, 0, .3]],
  };
  function play(name) {
    if (!sound || !SOUNDS[name]) return;
    const c = audio(); if (!c) return;
    for (const [f0, f1, dur, wave, vol, , delay = 0] of SOUNDS[name]) {
      const t = c.currentTime + delay, g = c.createGain();
      g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(.0001, t + dur);
      let src;
      if (wave === 'noise') {
        const b = c.createBuffer(1, Math.ceil(c.sampleRate * dur), c.sampleRate), d = b.getChannelData(0);
        for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
        src = c.createBufferSource(); src.buffer = b;
      } else {
        src = c.createOscillator(); src.type = wave; src.frequency.setValueAtTime(f0, t); src.frequency.exponentialRampToValueAtTime(f1, t + dur);
      }
      src.connect(g).connect(c.destination); src.start(t); src.stop(t + dur + .02);
    }
  }

  // ---------- seeded random: shuffles and daily puzzles ----------
  function rng(seed) {
    let h = 1779033703 ^ String(seed).length;
    for (const ch of String(seed)) { h = Math.imul(h ^ ch.charCodeAt(0), 3432918353); h = h << 13 | h >>> 19; }
    let a = h >>> 0;
    return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
  }
  const today = () => { const d = new Date(); return `${d.getFullYear()}-${d.getMonth() + 1}-${d.getDate()}`; };
  const daily = () => rng(`${cfg.id}:${today()}`);

  // ---------- particles ----------
  function burst(x, y, colors = ['#ffd23f', '#ff6b6b', '#4ecdc4', '#ffffff']) {
    if (calm) return;
    const layer = el('div', 'rc-burst'); document.body.append(layer);
    for (let i = 0; i < 22; i++) {
      const p = el('i'), a = Math.random() * Math.PI * 2, d = 50 + Math.random() * 90;
      p.style.cssText = `left:${x}px;top:${y}px;background:${colors[i % colors.length]};--dx:${Math.cos(a) * d}px;--dy:${Math.sin(a) * d - 30}px;--r:${Math.random() * 540 - 270}deg`;
      layer.append(p);
    }
    setTimeout(() => layer.remove(), 1000);
  }

  // ---------- stars, bests and the local high score board ----------
  const stars = key => store(`stars:${key}`) || 0;
  const best = key => store(`best:${key}`);
  function totalStars() {
    let n = 0;
    try { for (let i = 0; i < localStorage.length; i++) { const k = localStorage.key(i); if (k.startsWith(`recess:${cfg.id}:stars:`)) n += +localStorage.getItem(k) || 0; } } catch {}
    return n;
  }
  const better = (a, b) => b == null || (cfg.score.lower ? a < b : a > b);
  const boardOf = key => store(`board:${key}`) || [];
  const ranks = (list, score) => list.filter(r => !better(score, r.score)).length;   // place a score would take

  // ---------- the corner controls ----------
  function hud() {
    const bar = el('div', 'rc-hud'); bar.setAttribute('role', 'toolbar'); bar.setAttribute('aria-label', 'Game controls');
    const info = el('div', 'rc-info');
    info.append(el('b', 'rc-title', cfg.title), el('span', 'rc-level'), el('span', 'rc-stars'));
    const btn = (id, label, icon, fn, key) => {
      const b = el('button', 'rc-btn'); b.id = id; b.type = 'button'; b.title = `${label} (${key})`; b.setAttribute('aria-label', label);
      b.append(el('span', 'rc-ic', icon), el('span', 'rc-lb', label)); b.onclick = () => { play('tap'); fn(); }; return b;
    };
    bar.append(info,
      btn('rc-undo', 'Undo', '↶', () => undoOk && cfg.onUndo && cfg.onUndo(), 'U'),
      btn('rc-restart', 'Restart', '⟲', () => cfg.onRestart && cfg.onRestart(), 'R'),
      btn('rc-sound', 'Sound', '♪', () => { sound = !sound; try { localStorage.setItem('recess-sound', sound ? 'on' : 'off'); } catch {} paint(); if (sound) play('pop'); }, 'M'),
      btn('rc-motion', 'Motion', '✦', () => { calm = !calm; try { localStorage.setItem('curio-motion', calm ? 'calm' : 'on'); } catch {} paint(); }, 'none'),
      btn('rc-scores', 'Scores', '★', () => showScores(), 'S'));
    document.body.prepend(bar);
    addEventListener('keydown', e => {
      if (e.target.closest && e.target.closest('input,textarea,.rc-card')) return;
      const k = e.key.toLowerCase();
      if ((e.ctrlKey || e.metaKey) && k === 'z') { e.preventDefault(); $('rc-undo').click(); return; }
      if (e.ctrlKey || e.metaKey || e.altKey || document.querySelector('.rc-veil')) return;
      if (k === 'u') $('rc-undo').click();
      else if (k === 'r') $('rc-restart').click();
      else if (k === 'm') $('rc-sound').click();
      else if (k === 's') $('rc-scores').click();
    });
    paint();
  }
  function paint() {
    document.body.classList.toggle('calm', calm);
    const s = $('rc-sound'), m = $('rc-motion'), u = $('rc-undo');
    if (s) { s.setAttribute('aria-pressed', sound); s.querySelector('.rc-lb').textContent = sound ? 'Sound' : 'Muted'; }
    if (m) { m.setAttribute('aria-pressed', !calm); m.querySelector('.rc-lb').textContent = calm ? 'Calm' : 'Motion'; }
    if (u) u.disabled = !undoOk;
    const lv = document.querySelector('.rc-level'); if (lv) lv.textContent = levelLabel;
    const st = document.querySelector('.rc-stars'); if (st) st.textContent = `★ ${totalStars()}`;
    motionFns.forEach(f => f(calm));
  }

  // ---------- cards: win, initials, scores ----------
  let lastFocus = null;
  function card(build) {
    close();
    lastFocus = document.activeElement;
    const veil = el('div', 'rc-veil'), c = el('div', 'rc-card'); c.setAttribute('role', 'dialog'); c.setAttribute('aria-modal', 'true');
    build(c); veil.append(c); document.body.append(veil);
    veil.addEventListener('keydown', e => { if (e.key === 'Escape') close(); });
    veil.addEventListener('click', e => { if (e.target === veil) close(); });
    const f = c.querySelector('[data-first]') || c.querySelector('button'); if (f) f.focus();
    return c;
  }
  function close() { const v = document.querySelector('.rc-veil'); if (v) { v.remove(); if (lastFocus && lastFocus.focus) lastFocus.focus(); } }
  const starRow = n => { const r = el('div', 'rc-starrow'); r.setAttribute('aria-label', `${n} of 3 stars`); for (let i = 0; i < 3; i++) { const s = el('span', i < n ? 'on' : '', '★'); s.style.setProperty('--i', i); r.append(s); } return r; };

  function win({score, stars: n = 0} = {}) {
    const key = levelKey, prevBest = best(key), newBest = score != null && better(score, prevBest);
    if (n > stars(key)) store(`stars:${key}`, n);
    if (newBest) store(`best:${key}`, score);
    play('win'); paint();
    const list = boardOf(key), place = score == null ? 99 : ranks(list, score);
    card(c => {
      c.append(el('h2', 'rc-h', n === 3 ? 'Perfect!' : n ? 'Solved!' : 'Done!'), starRow(n));
      if (score != null) {
        const line = el('p', 'rc-score'); line.append(`${cfg.score.label}: `, el('b', null, String(score)));
        if (newBest && prevBest != null) line.append(el('span', 'rc-new', ' New best!'));
        c.append(line);
      }
      if (score != null && place < 10) initials(c, key, score);
      const row = el('div', 'rc-row');
      if (cfg.onNext) { const nx = el('button', 'rc-go', 'Next'); nx.onclick = () => { close(); cfg.onNext(); }; row.append(nx); }
      const again = el('button', 'rc-ghost', 'Play again'); again.onclick = () => { close(); cfg.onRestart && cfg.onRestart(); }; row.append(again);
      c.append(row);
    });
    const r = document.querySelector('.rc-starrow'); if (r) { const b = r.getBoundingClientRect(); burst(b.left + b.width / 2, b.top + b.height / 2); }
  }

  // three letter slots, each one up or down (or typed); never a name
  function initials(c, key, score) {
    const box = el('div', 'rc-init'), letters = (store('initials') || 'AAA').split('');
    box.append(el('p', 'rc-sub', 'A top 10 score! Your initials:'));
    const slots = el('div', 'rc-slots'); slots.setAttribute('role', 'group'); slots.setAttribute('aria-label', 'Initials, three letters');
    letters.forEach((ch, i) => {
      const s = el('div', 'rc-slot'), up = el('button', 'rc-arr', '▲'), dn = el('button', 'rc-arr', '▼'), v = el('input');
      v.maxLength = 1; v.value = ch; v.setAttribute('aria-label', `Letter ${i + 1}`); v.autocomplete = 'off'; v.spellcheck = false;
      if (!i) v.dataset.first = '';
      up.setAttribute('aria-label', `Letter ${i + 1} up`); dn.setAttribute('aria-label', `Letter ${i + 1} down`);
      const step = d => { letters[i] = String.fromCharCode((letters[i].charCodeAt(0) - 65 + d + 26) % 26 + 65); v.value = letters[i]; play('tap'); };
      up.onclick = () => step(1); dn.onclick = () => step(-1);
      v.onfocus = () => v.select();
      v.oninput = () => { v.value = letters[i]; };  // phones may type without a keydown letter: keep the slot honest
      v.onkeydown = e => {
        if (e.key === 'ArrowUp') { e.preventDefault(); step(1); }
        else if (e.key === 'ArrowDown') { e.preventDefault(); step(-1); }
        else if (e.key === 'Enter') { e.preventDefault(); save.click(); }
        else if (/^[a-z]$/i.test(e.key) && !e.ctrlKey && !e.metaKey) {
          e.preventDefault(); letters[i] = e.key.toUpperCase(); v.value = letters[i]; play('tap');
          (slots.querySelectorAll('input')[i + 1] || save).focus();
        }
      };
      v.addEventListener('beforeinput', e => {  // on-screen keyboards send a beforeinput with the letter
        const L = (e.data || '').toUpperCase().replace(/[^A-Z]/g, ''), ins = slots.querySelectorAll('input');
        if (!L) return; e.preventDefault();
        [...L].slice(0, 3 - i).forEach((ch, j) => { letters[i + j] = ch; ins[i + j].value = ch; });  // a pasted "CJB" fills all three
        (ins[Math.min(i + L.length, 3)] || save).focus();
      });
      s.append(up, v, dn); slots.append(s);
    });
    const save = el('button', 'rc-go', 'Save');
    save.onclick = () => {
      const name = letters.join(''); store('initials', name);
      const list = boardOf(key); list.push({name, score, at: Date.now()});
      list.sort((a, b) => cfg.score.lower ? a.score - b.score : b.score - a.score);
      store(`board:${key}`, list.slice(0, 10));
      box.replaceChildren(el('p', 'rc-sub', `Saved for ${name}.`)); play('pop');
    };
    box.append(slots, save); c.append(box);
  }

  function showScores() {
    card(c => {
      c.append(el('h2', 'rc-h', 'High scores'), el('p', 'rc-sub', `${levelLabel || cfg.title}. Saved on this computer only.`));
      const list = boardOf(levelKey);
      if (!list.length) c.append(el('p', 'rc-empty', 'No scores yet. Be the first!'));
      else {
        const ol = el('ol', 'rc-board');
        list.forEach(r => { const li = el('li'); li.append(el('b', null, r.name), el('span', null, String(r.score))); ol.append(li); });
        c.append(ol);
      }
      const b = best(levelKey);
      c.append(el('p', 'rc-sub', `Your stars in this game: ★ ${totalStars()}` + (b != null ? ` · Best here: ${b}` : '')));
      const row = el('div', 'rc-row'), ok = el('button', 'rc-go', 'Back to the game'); ok.onclick = close; row.append(ok); c.append(row);
    });
  }

  function start(o) {
    cfg = {...cfg, ...o, score: {...cfg.score, ...(o.score || {})}};
    document.body.classList.add('recess');
    hud();
    addEventListener('pointerdown', () => audio(), {once: true});
  }

  return {
    start, play, burst, rng, daily, store, stars, best, totalStars, win, close,
    level(key, label) { levelKey = String(key); levelLabel = label || ''; paint(); },
    canUndo(b) { undoOk = !!b; paint(); },
    onMotion(fn) { motionFns.push(fn); fn(calm); },
    get calm() { return calm; },
    get sound() { return sound; },
  };
})();
